-- LangChain + Snowflake Cortex LLM Integration Demo — Sample Data Setup
--
-- File   : ddl_and_data.sql
--
-- What this does:
--   1. Creates the demo schema
--   2. Creates 5 clinical tables (patients, providers, visits, diagnoses, medications)
--   3. Loads sample data
--
-- Prerequisites:
--   - Edit the variables below to match your environment
-- =============================================================================

SET MY_DATABASE = 'YOUR_DATABASE';   -- e.g. 'DEMO_DB'
SET MY_SCHEMA   = 'YOUR_SCHEMA';     -- e.g. 'CLINICAL'
SET MY_WH       = 'YOUR_WAREHOUSE';  -- e.g. 'COMPUTE_WH'

-- ---------------------------------------------------------------------------
-- Step 1 — Set session context
-- ---------------------------------------------------------------------------
USE WAREHOUSE IDENTIFIER($MY_WH);
USE DATABASE  IDENTIFIER($MY_DATABASE);

-- ---------------------------------------------------------------------------
-- Step 2 — Create schema
-- ---------------------------------------------------------------------------
CREATE SCHEMA IF NOT EXISTS IDENTIFIER($MY_SCHEMA)
    COMMENT = 'Sample clinical data for LangChain + Cortex integration demo.';
USE SCHEMA IDENTIFIER($MY_SCHEMA);

-- ---------------------------------------------------------------------------
-- Step 3 — Create tables (DDL)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE TABLE PATIENTS (
    patient_id      VARCHAR(10)     NOT NULL,
    full_name       VARCHAR(100)    NOT NULL,
    date_of_birth   DATE            NOT NULL,
    gender          VARCHAR(10),
    state           VARCHAR(2),
    phone           VARCHAR(20),
    CONSTRAINT pk_patients PRIMARY KEY (patient_id)
) COMMENT = 'Patient demographic master.';

CREATE OR REPLACE TABLE PROVIDERS (
    provider_id     VARCHAR(10)     NOT NULL,
    full_name       VARCHAR(100)    NOT NULL,
    specialty       VARCHAR(50),
    npi             VARCHAR(10),
    active_flag     BOOLEAN         NOT NULL,
    CONSTRAINT pk_providers PRIMARY KEY (provider_id)
) COMMENT = 'Clinician/provider master.';

CREATE OR REPLACE TABLE VISITS (
    visit_id        VARCHAR(10)     NOT NULL,
    patient_id      VARCHAR(10)     NOT NULL,
    provider_id     VARCHAR(10),
    visit_date      DATE            NOT NULL,
    visit_type      VARCHAR(30),
    CONSTRAINT pk_visits PRIMARY KEY (visit_id)
) COMMENT = 'Outpatient encounter records.';

CREATE OR REPLACE TABLE DIAGNOSES (
    diagnosis_id    VARCHAR(10)     NOT NULL,
    visit_id        VARCHAR(10)     NOT NULL,
    icd10_code      VARCHAR(10),
    description     VARCHAR(200),
    CONSTRAINT pk_diagnoses PRIMARY KEY (diagnosis_id)
) COMMENT = 'ICD-10 diagnosis codes per visit.';

CREATE OR REPLACE TABLE MEDICATIONS (
    medication_id   VARCHAR(10)     NOT NULL,
    visit_id        VARCHAR(10)     NOT NULL,
    drug_name       VARCHAR(100)    NOT NULL,
    dosage          VARCHAR(50),
    start_date      DATE,
    end_date        DATE,
    CONSTRAINT pk_medications PRIMARY KEY (medication_id)
) COMMENT = 'Prescription records per visit.';

